export async function fetchCover(isbn: string): Promise<Uint8Array | null> {
  for (let attempt = 0; attempt < 3; attempt++) {
    const res = await fetch(`https://covers.example/${isbn}`);
    if (res.ok) return new Uint8Array(await res.arrayBuffer());
  }
  return null;
}

